draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw a stick figure trying to hold on to something
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // Draw a line representing change, moving to the right
  ctx.beginPath();
  ctx.moveTo(0, H/2 + Math.sin(t) * 50);
  ctx.lineTo(W, H/2 + Math.sin(t) * 50);
  ctx.stroke();

  // Draw the stick figure's hands trying to hold on
  ctx.beginPath();
  ctx.arc(W/2 - 30, H/2 + 70, 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2 + 70, 10, 0, 2*Math.PI);
  ctx.stroke();

  // Draw a wave representing resistance, moving to the left
  ctx.beginPath();
  ctx.moveTo(0, H/2 + 100 + Math.cos(t) * 20);
  ctx.lineTo(W, H/2 + 100 + Math.cos(t + Math.PI) * 20);
  ctx.stroke();

  ctx.restore();
}
